import sys, json
sys.path.insert(0,'/workspace/site'); sys.path.insert(0,'/workspace/submission')
from formats import validate
def mk(rows_per):
    rows=[]
    for _ in range(rows_per):
        rows.append({'class':0,'values':[1515,1614,1414,1515,1614,1414,1515,1516,1517],
                     'activation':[0,100,100,0,100,100,0,0,0]})
    return rows
def release(rid, rows):
    return {'id':rid,'classes':2,'width':2,'eps':[1,1],'ratio':[0,1],'threshold':[1,1],'mode':'range',
            'packet_limit':3,'idle_us':10,'discovery':rows,
            'train':[{'class':0,'values':[1614,1414]},{'class':1,'values':[1814,1314]}],
            'validation':[{'class':0,'values':[1614,1414]},{'class':1,'values':[1814,1314]}]}
# 2 fragments per row
for a,b in ((2048,2048),(2049,2048),(2048,2047)):
    req = {'capacity':{'range':4,'exact':4},'releases':[release('a',mk(a)),release('b',mk(b))],'blocks':[]}
    try:
        validate(json.loads(json.dumps(req)))
        from pipeline import execute
        out = execute(req)
        print(a,b,'valid fragments', sum(len(c['fragments']) for c in out['catalog']))
